export default class App extends HTMLElement{constructor(){super(),slice.attachTemplate(this)}async init(){const t=await slice.build("Navbar",{position:"fixed",logo:{src:"/images/Slice.js-logo.png",path:"/"},items:[{text:"Home",path:"/"},{text:"Components",path:"/docs"}],buttons:[{value:"Change Theme",t:async()=>{const t=slice.stylesManager.themeManager.currentTheme;"Slice"===t?await slice.setTheme("Light"):"Light"===t?await slice.setTheme("Dark"):"Dark"===t&&await slice.setTheme("Slice")}}]}),e=this.querySelector(".app-navbar");e.appendChild(t);const a=await slice.build("MultiRoute",{routes:[{path:"/",component:"VisualLibraryHome",title:"Slice.js - Home"},{path:"/docs",component:"ComponentsPage",title:"Components Library"}]}),s=this.querySelector(".app-content");s.appendChild(a)}}customElements.define("slice-app",App);